    // Sum of this color's learned per-square weights for every one of its pieces currently
    // on the board, scaled up so fractional weight differences remain meaningful once
    // GameCPU.evaluateGameState rounds the result to an Int (minimax scores are Int throughout).
    static func score(for color: String, gameState: GameState) -> Int {
        guard let colorTable = weights[color] else { return 0 }
        var total = 0.0
        for index in 0..<GameState.tileCount {
            guard let piece = gameState.board[index], piece.color == color else { continue }
            if let table = colorTable[piece.type] {
                total += table[index]
            }
        }
        return Int((total * 100.0).rounded())
    }
